package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.history.AsOf;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of sheets. A sheet never stored is an empty sheet whose today is the real date. */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        List<Sheet> found = jdbc.query("SELECT today_date, archived FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(id, rs.getObject(1, LocalDate.class), rs.getBoolean(2)), id);
        return found.isEmpty() ? new Sheet(id, LocalDate.now(), false) : found.get(0);
    }

    /** The sheet's today: use this, never the real clock, for anything that depends on the date. */
    public LocalDate today(String id) {
        // While the store is read as of a date, that date stands in for the sheet's today.
        return AsOf.date() != null ? AsOf.date() : find(id).today();
    }

    /** Whether the sheet is archived, and so refuses every change. */
    public boolean isArchived(String id) {
        return find(id).archived();
    }

    public void save(Sheet sheet) {
        jdbc.update("MERGE INTO sheet (id, today_date, archived) KEY (id) VALUES (?, ?, ?)", sheet.id(), sheet.today(),
                sheet.archived());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    // A sheet that was never loaded before starts empty, so any id loads.
    public void load(@PathVariable("sheetId") String sheetId, Sheets sheets, Out<Sheet> sheetOut) {
        sheetOut.set(sheets.find(sheetId.trim()));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, ObjectResponse<SheetResponse> response) {
        response.send(SheetResponse.from(sheet));
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of who names whom as their patron, kept per sheet through the people. */
@Repository
public class Patrons {

    private final JdbcTemplate jdbc;

    public Patrons(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every person-to-patron link on the sheet. */
    public List<PatronResponse> list(String sheetId) {
        return jdbc.query("SELECT pp.person_id, pp.patron_id FROM person_patron pp"
                + " JOIN person p ON p.id = pp.person_id WHERE p.sheet_id = ? ORDER BY pp.person_id, pp.patron_id",
                (rs, n) -> new PatronResponse(rs.getLong("person_id"), rs.getLong("patron_id")), sheetId);
    }

    public boolean has(long personId, long patronId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person_patron WHERE person_id = ? AND patron_id = ?",
                Integer.class, personId, patronId);
        return n != null && n > 0;
    }

    public void add(long personId, long patronId) {
        jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)", personId, patronId);
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of which signed-in users watch which people, kept per sheet through the people. */
@Repository
public class Watches {

    private final JdbcTemplate jdbc;

    public Watches(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every watch on the sheet, in the order they started. */
    public List<WatchResponse> list(String sheetId) {
        return jdbc.query("SELECT w.person_id, w.user_name FROM person_watch w"
                + " JOIN person p ON p.id = w.person_id WHERE p.sheet_id = ? ORDER BY w.id",
                (rs, n) -> new WatchResponse(rs.getLong("person_id"), rs.getString("user_name")), sheetId);
    }

    /** The users watching the person, in the order they started watching. */
    public List<String> watchers(long personId) {
        return jdbc.queryForList("SELECT user_name FROM person_watch WHERE person_id = ? ORDER BY id", String.class,
                personId);
    }

    public boolean has(long personId, String user) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM person_watch WHERE person_id = ? AND user_name = ?",
                Integer.class, personId, user);
        return n != null && n > 0;
    }

    public void add(long personId, String user) {
        jdbc.update("INSERT INTO person_watch (person_id, user_name) VALUES (?, ?)", personId, user);
    }

    public void remove(long personId, String user) {
        jdbc.update("DELETE FROM person_watch WHERE person_id = ? AND user_name = ?", personId, user);
    }
}
package net.officefloor.hq.app.statement;

import java.sql.Date;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of statements, kept per sheet. */
@Repository
public class Statements {

    private final JdbcTemplate jdbc;

    public Statements(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Locks the person's row until the transaction commits, so two statements of them are taken one after the other. */
    public void lock(long personId) {
        jdbc.queryForList("SELECT id FROM person WHERE id = ? FOR UPDATE", personId);
    }

    public void add(Statement statement) {
        jdbc.update("INSERT INTO statement (sheet_id, person_id, due_total, claims, stated_on) VALUES (?, ?, ?, ?, ?)",
                statement.sheetId(), statement.personId(), statement.dueTotal(), statement.claims(),
                Date.valueOf(statement.statedOn()));
    }

    /** Removes the person's last statement and returns it; null when they have none. */
    public CancelledStatement removeLast(String sheetId, long personId) {
        List<Map<String, Object>> last = jdbc.queryForList("SELECT id, due_total FROM statement "
                + "WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 1", sheetId, personId);
        if (last.isEmpty()) {
            return null;
        }
        jdbc.update("DELETE FROM statement WHERE id = ?", last.get(0).get("id"));
        return new CancelledStatement((String) last.get(0).get("due_total"));
    }

    /** Each person of the sheet who has a statement: their count, and their last statement's due-total and date. */
    public List<StatementResponse> list(String sheetId) {
        return jdbc.query("SELECT s.person_id, c.n, s.due_total, s.stated_on FROM statement s "
                + "JOIN (SELECT person_id, COUNT(*) AS n, MAX(id) AS last_id FROM statement WHERE sheet_id = ? "
                + "GROUP BY person_id) c ON s.id = c.last_id ORDER BY s.person_id",
                (rs, n) -> new StatementResponse(rs.getLong(1), rs.getInt(2), rs.getString(3),
                        rs.getDate(4).toLocalDate().toString()),
                sheetId);
    }

    public StatementResponse find(String sheetId, long personId) {
        return list(sheetId).stream().filter(s -> s.personId() == personId).findFirst()
                .orElse(new StatementResponse(personId, 0, null, null));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The store of periods, kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"), Map.of(),
            rs.getBoolean("soft"));

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date, each closed one with its people's fixed figures. */
    public List<Period> list(String sheetId) {
        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
        jdbc.query("SELECT * FROM period_person_total WHERE sheet_id = ? ORDER BY person_id", rs -> {
            totals.computeIfAbsent(rs.getString("period_name"), k -> new LinkedHashMap<>())
                    .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
        }, sheetId);
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId).stream()
                .map(p -> p.withPersonTotals(totals.getOrDefault(p.name(), Map.of()))).toList();
    }

    /** The sheet's period of that name, or null when there is none. */
    public Period find(String sheetId, String name) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ?", ROW, sheetId, name).stream()
                .findFirst().orElse(null);
    }

    /** The sheet's period containing the date, or null when none does. */
    public Period on(String sheetId, LocalDate date) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND from_date <= ? AND ? <= to_date",
                ROW, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    /** The sheet's closed period containing the date, or null when none does. */
    public Period closedOn(String sheetId, LocalDate date) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND ? <= to_date",
                ROW, sheetId, Date.valueOf(date), Date.valueOf(date)).stream().findFirst().orElse(null);
    }

    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
    }

    /**
     * Closes the period (open or soft-closed), fixing its total and its people's figures afresh; false when it was
     * already closed (by someone else).
     */
    public boolean close(Period closed) {
        if (jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
                closed.closedTotal(), closed.sheetId(), closed.name()) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", closed.sheetId(),
                closed.name());
        insertPersonTotals(closed);
        return true;
    }

    /** Soft-closes the open period, fixing its total and its people's figures; false when it was not open (any more). */
    public boolean softClose(Period soft) {
        if (jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft",
                soft.closedTotal(), soft.sheetId(), soft.name()) != 1) {
            return false;
        }
        insertPersonTotals(soft);
        return true;
    }

    private void insertPersonTotals(Period closed) {
        closed.personTotals().forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                closed.sheetId(), closed.name(), personId, total));
    }

    /** Reopens the (soft-)closed period, dropping its fixed total; false when it was not closed (someone else reopened it). */
    public boolean reopen(Period period) {
        if (jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ? AND (closed OR soft)",
