package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

public class RefuseArchived {
    // An archived sheet keeps everything visible and changes nothing: every write is refused before anything is read, stored or recorded.
    public void refuse(@PathVariable("sheetId") String sheetId, Sheets sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived: it can change nothing.");
        }
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleSheetArchived {
    public void handle(@Parameter SheetArchivedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
    }
}
package net.officefloor.hq.app.sheet;

/** A change asked of an archived sheet, which changes nothing more. */
public class SheetArchivedException extends Exception {

    public SheetArchivedException(String message) {
        super(message);
    }
}
